mapper.sql:
WHERE do.camp_id = #{campId}
  AND om.is_deleted = 0
  AND om.order_type = 'daily_room'

    AND om.created_at >= #{bookingStart}


    AND om.created_at < #{bookingEndExclusive}


    AND (
        om.order_no LIKE CONCAT('%', #{keyword}, '%')
        OR om.out_order_no LIKE CONCAT('%', #{keyword}, '%')
        OR om.guest_name LIKE CONCAT('%', #{keyword}, '%')
        OR om.guest_mobile LIKE CONCAT('%', #{keyword}, '%')
        OR rc.name LIKE CONCAT('%', #{keyword}, '%')
    )




            AND COALESCE(TRIM(om.remark), '') = '置换订单'


            AND COALESCE(TRIM(om.remark), '') != '置换订单'




    AND do.settlement_status = #{settledState}
